def transform(grid):
    if not grid:
        return grid
    rows = len(grid)
    cols = len(grid[0])
    bg_color = grid[0][0]
    output = [row[:] for row in grid]

    ranges = {}
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == bg_color:
                continue
            if color not in ranges:
                ranges[color] = [r, r, c, c]
            else:
                ranges[color][0] = min(ranges[color][0], r)
                ranges[color][1] = max(ranges[color][1], r)
                ranges[color][2] = min(ranges[color][2], c)
                ranges[color][3] = max(ranges[color][3], c)

    for color in ranges:
        min_r, max_r, min_c, max_c = ranges[color]
        for r in range(min_r + 1, max_r):
            for c in range(min_c + 1, max_c):
                output[r][c] = 8
    return output
